using System.Security.Claims;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Primitives;
using SistemaPedagogico.Infrastructure.Storage;
using SistemaPedagogico.Web.Portal;
namespace SistemaPedagogico.Tests;
public class PortalTests : IDisposable {
 readonly SqliteConnection connection=new("Data Source=:memory:");readonly EducaDb db;readonly string directory;
 public PortalTests(){connection.Open();db=new EducaDb(new DbContextOptionsBuilder<EducaDb>().UseSqlite(connection).Options);db.Database.EnsureCreated();directory=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);db.Students.AddRange(new Student{Id=1,Name="Aluno A",SubjectIds="1"},new Student{Id=2,Name="Aluno B",SubjectIds="1"});db.Teachers.Add(new Teacher{Id=1,Name="Professor",SubjectIds="1",Days="1,2,3,4,5,6,7",StartHour=0,EndHour=24});db.Subjects.Add(new Subject{Id=1,Name="Matemática"});db.Enrollments.Add(new Enrollment{StudentId=1,TeacherId=1});db.SaveChanges();}
 PortalController Controller(string role,int entity){var http=new DefaultHttpContext();http.User=new ClaimsPrincipal(new ClaimsIdentity(new[]{new Claim(ClaimTypes.Role,role),new Claim(ClaimTypes.NameIdentifier,"99"),new Claim("entity",entity.ToString())},"Test"));var c=new PortalController(db,new StoragePaths{DataDirectory=directory}){ControllerContext=new ControllerContext{HttpContext=http}};c.TempData=new TempDataDictionary(http,new TestTempData());return c;}
 static FormCollection Form(params (string key,string value)[] entries)=>new(entries.ToDictionary(x=>x.key,x=>new StringValues(x.value)));
 [Fact] public async Task Aluno_nao_acessa_financeiro(){Assert.IsType<ForbidResult>(await Controller("Aluno",1).Index("mensalidades"));}
 [Fact] public async Task Aluno_so_recebe_seus_registros(){var result=Assert.IsType<ViewResult>(await Controller("Aluno",1).Index());var model=Assert.IsType<PortalVm>(result.Model);Assert.Single(model.Students);Assert.Equal(1,model.Students[0].Id);}
 [Fact] public async Task Professor_nao_recebe_aluno_sem_vinculo(){var result=Assert.IsType<ViewResult>(await Controller("Professor",1).Index("alunos"));var model=Assert.IsType<PortalVm>(result.Model);Assert.Single(model.Students);Assert.Equal(1,model.Students[0].Id);}
 [Fact] public async Task Aluno_nao_entrega_atividade_de_outro(){db.Activities.Add(new Activity{Id=1,StudentId=2,Title="Teste"});db.SaveChanges();var result=await Controller("Aluno",1).Save("submit",Form(("Id","1"),("Answer","Minha resposta")),null);Assert.IsType<ForbidResult>(result);Assert.Equal("Pendente",(await db.Activities.FindAsync(1))!.Status);}
 [Fact] public async Task Aula_com_conflito_nao_e_salva(){var start=DateTime.Today.AddDays(2).AddHours(10);db.Lessons.Add(new Lesson{StudentId=1,TeacherId=1,SubjectId=1,Start=start,Minutes=60});db.SaveChanges();var c=Controller("Aluno",1);await c.Save("lesson",Form(("TeacherId","1"),("SubjectId","1"),("Start",start.AddMinutes(30).ToString("yyyy-MM-ddTHH:mm")),("Minutes","60"),("Mode","Presencial")),null);Assert.Equal(1,await db.Lessons.CountAsync());Assert.Contains("conflito",c.TempData["Error"]?.ToString());}
 [Fact] public async Task Aula_fora_da_disponibilidade_nao_e_salva(){var t=await db.Teachers.FindAsync(1);t!.StartHour=14;t.EndHour=18;await db.SaveChangesAsync();var c=Controller("Aluno",1);await c.Save("lesson",Form(("TeacherId","1"),("SubjectId","1"),("Start",DateTime.Today.AddDays(2).AddHours(10).ToString("yyyy-MM-ddTHH:mm")),("Minutes","60"),("Mode","Presencial")),null);Assert.Empty(await db.Lessons.ToListAsync());Assert.Contains("disponibilidade",c.TempData["Error"]?.ToString());}
 [Fact] public async Task Aluno_nao_lanca_notas(){var result=await Controller("Aluno",1).Save("grade",Form(("StudentId","1"),("SubjectId","1"),("Value","9")),null);Assert.IsType<ForbidResult>(result);Assert.Empty(await db.Grades.ToListAsync());}
 [Fact] public async Task Agendamento_valido_e_persistido(){var c=Controller("Aluno",1);await c.Save("lesson",Form(("TeacherId","1"),("SubjectId","1"),("Start",DateTime.Today.AddDays(2).AddHours(10).ToString("yyyy-MM-ddTHH:mm")),("Minutes","60"),("Mode","Online")),null);var lesson=Assert.Single(await db.Lessons.ToListAsync());Assert.Equal(1,lesson.StudentId);Assert.Equal("Agendada",lesson.Status);}
 static FormCollection StudentForm(string phone,string guardianPhone="",string status="Ativo")=>Form(("Id","1"),("Name","Aluno A"),("Phone",phone),("GuardianPhone",guardianPhone),("Level","Ensino Fundamental II"),("Shift","Tarde"),("Status",status),("SubjectIds","1"));
 [Theory][InlineData("abc")][InlineData("69999")][InlineData("69999999999999")][InlineData("6912345678")]
 public async Task Telefone_invalido_nao_e_persistido(string phone){var c=Controller("Admin",0);await c.Save("student",StudentForm(phone),null);Assert.Contains("Telefone inválido",c.TempData["Error"]?.ToString());db.ChangeTracker.Clear();Assert.Equal("",(await db.Students.FindAsync(1))!.Phone);}
 [Fact] public async Task Telefone_do_responsavel_tambem_e_validado(){var c=Controller("Admin",0);await c.Save("student",StudentForm("69999998888","letras"),null);Assert.Contains("Telefone inválido",c.TempData["Error"]?.ToString());db.ChangeTracker.Clear();Assert.Equal("",(await db.Students.FindAsync(1))!.GuardianPhone);}
 [Fact] public async Task Telefone_valido_e_formatado(){var c=Controller("Admin",0);await c.Save("student",StudentForm("+55 (69) 99999-8888"),null);Assert.Null(c.TempData["Error"]);Assert.Equal("(69) 99999-8888",(await db.Students.FindAsync(1))!.Phone);}
 [Fact] public async Task Formado_preserva_historico(){db.Grades.Add(new Grade{StudentId=1,SubjectId=1,Value=8});await db.SaveChangesAsync();await Controller("Admin",0).Save("student-status",Form(("Id","1"),("Status","Formado")),null);Assert.Equal("Formado",(await db.Students.FindAsync(1))!.Status);Assert.False((await db.Students.FindAsync(1))!.Active);Assert.Single(await db.Grades.ToListAsync());}
 [Fact] public async Task Exclusao_com_historico_e_recusada(){db.Grades.Add(new Grade{StudentId=1,SubjectId=1,Value=8});await db.SaveChangesAsync();var c=Controller("Admin",0);await c.Save("delete-student",Form(("Id","1"),("ConfirmDelete","true")),null);Assert.Contains("histórico",c.TempData["Error"]?.ToString());Assert.NotNull(await db.Students.FindAsync(1));}
 [Fact] public async Task Exclusao_sem_historico_remove_vinculos_e_acesso(){db.Users.Add(new PortalUser{Name="Aluno A",Email="aluno@example.com",Role="Aluno",EntityId=1});await db.SaveChangesAsync();await Controller("Admin",0).Save("delete-student",Form(("Id","1"),("ConfirmDelete","true")),null);Assert.Null(await db.Students.FindAsync(1));Assert.Empty(await db.Enrollments.Where(x=>x.StudentId==1).ToListAsync());Assert.Empty(await db.Users.Where(x=>x.EntityId==1).ToListAsync());}
 [Fact] public async Task Professor_nao_exclui_aluno(){Assert.IsType<ForbidResult>(await Controller("Professor",1).Save("delete-student",Form(("Id","1"),("ConfirmDelete","true")),null));Assert.NotNull(await db.Students.FindAsync(1));}

 [Fact] public async Task Cadastro_gera_mensalidades_uma_unica_vez(){
 var c=Controller("Admin",0);var form=Form(("Name","maria   silva"),("Guardian","joao silva"),("Level","Pré-escola"),("Shift","Manhã"),("Status","Ativo"),("ServiceType","Ambos"),("SubjectIds","1"),("RegistrationKey",Guid.NewGuid().ToString()),("BillingMonths","3"),("MonthlyAmount","200"),("FirstDue","2026-01-31"));
 await c.Save("student",form,null);Assert.Null(c.TempData["Error"]);db.ChangeTracker.Clear();await c.Save("student",form,null);Assert.Equal(3,await db.Payments.CountAsync());var student=await db.Students.SingleAsync(x=>x.Name=="Maria Silva");Assert.Equal("Ambos",student.ServiceType);var payments=await db.Payments.OrderBy(x=>x.Due).ToListAsync();Assert.Equal(new DateTime(2026,2,28),payments[1].Due);Assert.All(payments,x=>Assert.Equal(200m,x.Amount));
 }
 [Fact] public async Task Crianca_menor_de_quatro_anos_e_recusada(){var c=Controller("Admin",0);await c.Save("student",Form(("Id","1"),("Name","Aluno Teste"),("BirthDate",DateTime.Today.AddYears(-3).ToString("yyyy-MM-dd"))),null);Assert.Contains("4 anos",c.TempData["Error"]?.ToString());}
 [Fact] public async Task Professor_exige_nome_e_sobrenome(){var c=Controller("Admin",0);await c.Save("teacher",Form(("Name","Maria")),null);Assert.Contains("sobrenome",c.TempData["Error"]?.ToString());}
 [Fact] public async Task Atividade_permite_somente_arquivo_e_multiplos_alunos(){db.Enrollments.Add(new Enrollment{StudentId=2,TeacherId=1});await db.SaveChangesAsync();var c=Controller("Professor",1);using var stream=new MemoryStream(new byte[]{1,2,3});var file=new FormFile(stream,0,3,"attachment","atividade.pdf");await c.Save("activity",Form(("StudentIds","1,2"),("SubjectId","1"),("Title","Leitura"),("Due","2026-12-01")),file);Assert.Null(c.TempData["Error"]);var activities=await db.Activities.ToListAsync();Assert.Equal(2,activities.Count);Assert.All(activities,x=>Assert.Equal("atividade.pdf",x.AssignmentName));Assert.Single(Directory.GetFiles(Path.Combine(directory,"Arquivos")));}
 [Fact] public async Task Horarios_excluem_conflitos(){var date=DateTime.Today.AddDays(2);db.Lessons.Add(new Lesson{StudentId=1,TeacherId=1,SubjectId=1,Start=date.AddHours(10),Minutes=60});await db.SaveChangesAsync();var result=Assert.IsType<JsonResult>(await Controller("Aluno",1).Slots(1,1,1,date,60));var slots=Assert.IsType<List<string>>(result.Value);Assert.DoesNotContain(date.AddHours(10).ToString("yyyy-MM-ddTHH:mm"),slots);Assert.Contains(date.AddHours(11).ToString("yyyy-MM-ddTHH:mm"),slots);}
 [Fact] public async Task Progresso_estruturado_preserva_proximos_passos(){var c=Controller("Professor",1);await c.Save("progress",Form(("StudentId","1"),("ServiceType","Reforço escolar"),("Date","2026-10-07"),("Difficulty","Multiplicação"),("Goal","Resolver contas"),("Worked","Material concreto"),("Evolution","Menos ajuda"),("NextSteps","Praticar")),null);Assert.Null(c.TempData["Error"]);Assert.Equal("Praticar",(await db.Progress.SingleAsync()).NextSteps);}

 [Fact] public async Task Atualizacao_v3_adiciona_campos_e_preserva_cadastro(){
 db.Settings.Add(new PortalSetting{Key="legacy-import",Value="test"});await db.SaveChangesAsync();
 foreach(var item in new[]{("Students","ServiceType"),("Students","RegistrationKey"),("Lessons","OnlineUrl"),("Grades","Source"),("Activities","Origin"),("Activities","AssignmentKey"),("Activities","AssignmentName"),("Progress","ServiceType"),("Progress","SubjectId"),("Progress","Difficulty"),("Progress","Goal"),("Progress","Worked"),("Progress","Evolution"),("Progress","NextSteps"),("Progress","Tasks"),("Progress","Autonomy")})await db.Database.ExecuteSqlRawAsync("ALTER TABLE "+item.Item1+" DROP COLUMN "+item.Item2);
 using var oldConnection=new SqliteConnection("Data Source=:memory:");oldConnection.Open();using var old=new SistemaPedagogico.Infrastructure.Data.SistemaPedagogicoDbContext(new DbContextOptionsBuilder<SistemaPedagogico.Infrastructure.Data.SistemaPedagogicoDbContext>().UseSqlite(oldConnection).Options);
 await PortalBootstrap.ImportAsync(db,old);db.ChangeTracker.Clear();Assert.Equal("Aluno A",(await db.Students.FindAsync(1))!.Name);Assert.Equal("Reforço escolar",(await db.Students.FindAsync(1))!.ServiceType);await PortalBootstrap.ImportAsync(db,old);Assert.Equal(2,await db.Students.CountAsync());
 }
 public void Dispose(){db.Dispose();connection.Dispose();Directory.Delete(directory,true);}
 class TestTempData:ITempDataProvider {public IDictionary<string,object> LoadTempData(HttpContext context)=>new Dictionary<string,object>();public void SaveTempData(HttpContext context,IDictionary<string,object> values){} }
}
